@app.get("/", response_class=HTMLResponse)
def home():
    return HTML

@app.post("/submit-requirements")
def submit_requirements(req: PlanRequest):
    # The submitted information is available to your server.
    # This does NOT redirect the customer or automatically message them.
    print("NEW CUSTOMER REQUIREMENT RECEIVED")
    print(req.model_dump())
    return {"ok": True, "message": "Requirements received successfully."}


